import javassist.*;import javassist.expr.*;import java.util.*;import java.util.jar.*;import java.nio.file.*;
public class PatchDiagnosticExits {public static void main(String[] args)throws Exception{String src=args[0],dst=args[1];ClassPool p=new ClassPool(false);p.appendClassPath(src);p.appendClassPath("/tmp/music-tools/platform33/android-13/android.jar");Map<String,byte[]> changes=new HashMap<>();for(String n:new String[]{"com.tencent.shadow.core.runtime.container.PluginContainerActivity","com.tencent.shadow.core.runtime.container.NativePluginContainerActivity"}){CtClass c=p.get(n);c.instrument(new ExprEditor(){public void edit(MethodCall m)throws CannotCompileException{if(m.getClassName().equals("java.lang.System")&&m.getMethodName().equals("exit"))m.replace("{ paradox.music.nativeui.NativeMusicDiagnostics.exitAttempt($1); $proceed($$); }");}});changes.put(n.replace('.','/')+".class",c.toBytecode());}try(JarFile in=new JarFile(src);JarOutputStream out=new JarOutputStream(Files.newOutputStream(Paths.get(dst)))){var es=in.entries();while(es.hasMoreElements()){var e=es.nextElement();out.putNextEntry(new JarEntry(e.getName()));out.write(changes.containsKey(e.getName())?changes.get(e.getName()):in.getInputStream(e).readAllBytes());out.closeEntry();}}System.out.println("Recorded container exits without changing exit behavior: "+changes.size());}}
